mutants_x__fetch_news__mutmut: MutantDict = {}  # type: ignore


@_mutmut_mutated(mutants_x__fetch_news__mutmut)
def _fetch_news(ticker: str, days: int) -> list[dict]:
    cached = _cache.get(ticker)
    if cached and time.time() - cached[1] < CACHE_TTL:
        return cached[0]

    try:
        import finnhub
        from config import get_settings

        settings = get_settings()
        if not settings.finnhub_api_key:
            return []

        client = finnhub.Client(api_key=settings.finnhub_api_key)
        _track_call()
        to_dt = datetime.now()
        from_dt = to_dt - timedelta(days=days)
        raw = client.company_news(
            ticker,
            _from=from_dt.strftime("%Y-%m-%d"),
            to=to_dt.strftime("%Y-%m-%d"),
        )
        result = raw[:10] if raw else []
        _cache[ticker] = (result, time.time())
        return result
    except Exception:
        return []


