async def get_company_news(ticker: str, days: int = 7) -> list[dict]:
    t = ticker.upper()
    cache_key = f"news:company_news:{t}:{days}"
    redis_cached = await cache_get(cache_key)
    if redis_cached is not None:
        return redis_cached

    raw = await asyncio.get_running_loop().run_in_executor(_executor, _fetch_news, t, days)

    items = []
    for item in raw[:6]:
        headline = item.get("headline", "")
        summary = item.get("summary", headline)
        ts = item.get("datetime", 0)
        hours_ago = max(0, int((time.time() - ts) / 3600)) if ts else 0
        items.append(
            {
                "headline": headline,
                "summary": summary[:300] if summary else headline,
                "sentiment": score_sentiment(headline + " " + summary),
                "hours_ago": hours_ago,
                "source": item.get("source", "Finnhub"),
                "url": item.get("url", ""),
            }
        )
    if items:
        await cache_set(cache_key, items, ttl=900)
    return items


